(() => {
  'use strict';
  const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let data={pensions:[],sources:[],people:[],offices:[],grievances:[],tasks:[],documents:[],approvals:[],connections:[],knowledge:[],stats:{}},actor=null,route='search',selectedCase=null,tab='Overview',conversation=[],conversationId=null,pending=false,searchText='',appsFilter='All',chartScale=1;
  const suggestions=[
    'Investigate a pension case',
    'Review pending grievances',
    'Find a government rule',
    'Prepare an office note',
    'Analyse pension delays',
    'Review my pending work'
  ];
  const suggestionQueries=[
    'Investigate Pranab Kumar Deka pension case PEN-NGN-2026-041 and identify the recorded delay.',
    'Compare grievances GRV-AS-2026-01192 and GRV-AS-2026-01874 for PEN-NGN-2026-041.',
    'Find indexed source records that mention the applicable pension rule; report if no authoritative rule is supplied.',
    'Review case PEN-NGN-2026-041 and prepare an office note from its authorised records.',
    'Analyse the service discrepancy and recorded pension delay for PEN-NGN-2026-041.',
    'Review my assigned pending work and due dates.'
  ];
  const icon=name=>{const p={Search:'<circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.5 4.5"/>',History:'<path d="M3 12a9 9 0 1 0 2.6-6.4L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/>',Attachment:'<path d="m21.4 11.1-8.5 8.5a6 6 0 0 1-8.5-8.5l9.2-9.2a4 4 0 0 1 5.7 5.7L9.4 17.5a2 2 0 0 1-2.8-2.8l8.5-8.5"/>',Microphone:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',Apps:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',People:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',Pensions:'<path d="M3 21h18M5 21V8l7-4 7 4v13M9 21v-8h6v8M8 9h.01M12 9h.01M16 9h.01"/>',Grievances:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 8.7 3.9a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/>',Documents:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',Files:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',Knowledge:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',Approvals:'<path d="m9 12 2 2 4-4"/><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11z"/>',Work:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 12h18M10 12v2h4v-2"/>',Analytics:'<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-5 5"/>',Audit:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11z"/><path d="m9 12 2 2 4-4"/>',Meetings:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m10 9 5 3-5 3z"/>',Reports:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 16l2-2 2 2 4-4"/>',Productivity:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h8M8 17h5"/>',Government:'<path d="m3 9 9-6 9 6M5 10v9m5-9v9m4-9v9m5-9v9M3 21h18"/>',Other:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8m-4-4h8"/>'};return `<svg class="lucide" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.Other}</svg>`};
  async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let b;try{b=await r.json()}catch{b={error:'Unexpected server response'}}if(!r.ok)throw new Error(b.error||`Request failed (${r.status})`);return b}
  function toast(s){const t=$('#toast');t.textContent=s;t.hidden=false;setTimeout(()=>t.hidden=true,2800)}
  function nav(r,caseId){route=r;selectedCase=caseId||selectedCase;history.pushState({route,caseId},'',`#${r}${caseId?'/'+encodeURIComponent(caseId):''}`);render()}
  window.addEventListener('popstate',()=>{parseRoute();render()});
  function parseRoute(){const x=location.hash.slice(1).split('/');route=x[0]||'search';selectedCase=x[1]?decodeURIComponent(x[1]):null;}
  function getCase(id){return data.pensions.find(p=>p.id===id||p.case_id===id)}
  function person(id){return data.people.find(p=>p.id===id)}
  function source(id){return data.sources.find(d=>d.id===id)}
  function statusPill(s){let v=String(s||'').toLowerCase();let cl=/approved|complete|allowed|connected/.test(v)?'green':/pending|prepared|requested|review|submitted/.test(v)?'amber':/denied|rejected|blocked|failed/.test(v)?'red':'blue';return `<span class="chip ${cl}">${esc(String(s||'—').replaceAll('_',' '))}</span>`}
  function render(){
    $('#crumb').textContent=({search:'Search',apps:'Apps',people:'People',profile:'Profile',pensions:'Pensions',grievances:'Grievances',files:'Files',knowledge:'Knowledge',approvals:'Approvals',work:'Work',analytics:'Analytics',audit:'Audit',meetings:'Meetings',reports:'Reports'}[route]||'Search');
    document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('selected',b.dataset.route===(['search','apps','people'].includes(route)?route:'apps')));
    $('#personaName').textContent=actor?.name||'Officer';$('#personaRole').textContent=actor?.designation||'Workspace profile';
    const views={search:searchView,apps:appsView,people:peopleView,profile:profileView,pensions:pensionsView,grievances:grievancesView,files:filesView,knowledge:knowledgeView,approvals:approvalsView,work:workView,analytics:analyticsView,audit:auditView,meetings:()=>moduleStub('Meetings','Meeting records are not included in the supplied workspace data.'),projects:()=>moduleStub('Projects','Project tracking records are not included in the supplied workspace data.'),forms:()=>moduleStub('Forms','Form templates and submissions are not included in the supplied workspace data.'),reports:reportsView};
    $('#view').innerHTML=(views[route]||searchView)();wire();
  }
  function searchView(){
    if(!conversation.messages?.length)return `<div class="search-page"><div class="search-tools"><button class="icon-button" id="historyBtn" title="Conversation history" aria-label="Conversation history">${icon('History')}</button><button class="soft-btn" id="newChat"><span class="plus">+</span> New conversation</button></div><div class="search-title"><div class="lotus-mark"><img src="/assets/brand/lotus.png" alt=""></div><div class="brand-line">Your work, connected.</div><h1 class="page-title">Start your day with Singularity</h1></div><form class="composer" id="askForm"><textarea id="askInput" placeholder="Search anything or ask Singularity to do something..." aria-label="Search anything or ask Singularity to do something" required></textarea><div class="composer-foot"><div class="composer-tools"><button type="button" class="icon-button" id="attachBtn" title="Add attachment" aria-label="Add attachment">${icon('Attachment')}</button><button type="button" class="source-select" id="sourceSelect">${icon('Documents')} <span>Select sources</span></button></div><div class="composer-tools"><button type="button" class="icon-button" id="voiceBtn" title="Voice input unavailable" aria-label="Voice input unavailable">${icon('Microphone')}</button><button class="send-btn" type="submit" title="Search" aria-label="Send">&#8593;</button></div></div></form><div class="suggestion-grid">${['Investigate a pension case','Review pending grievances','Find a government rule','Prepare an office note','Analyse pension delays','Review my pending work'].map((label,i)=>`<button class="suggestion" data-suggest="${i}"><span class="suggestion-icon">${icon(['Search','Grievances','Knowledge','Documents','Analytics','Work'][i])}</span>${label}</button>`).join('')}</div><div class="access-note"><span class="access-shield">${icon('Audit')}</span> Only answers from information you have access to.</div></div>`;
    return `<div class="conversation"><div class="conversation-top"><strong>${esc(conversation.title||'New conversation')}</strong><div class="conversation-actions"><button class="soft-btn" id="newChat">+ New conversation</button><button class="soft-btn" id="historyBtn">History</button></div></div><div class="messages">${conversation.messages.map(m=>m.role==='user'?`<div class="user-message">${esc(m.body)}</div>`:`<div class="assistant-message"><p>${esc(m.body)}</p>${m.table?`<table class="result-table"><thead><tr>${m.table.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${m.table.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:''}${m.steps?.length?`<div class="tool-steps">${m.steps.map(s=>`<span class="tool-step">${esc(s.label)}</span>`).join('')}</div>`:''}${m.citations?.length?`<div class="inline-citations">${m.citations.map(c=>`<button class="citation" data-source="${esc(c.id)}"><span>${icon('Documents')}</span><b>${esc(c.title)}</b><small>${esc(c.location)} &middot; v${c.version}</small></button>`).join('')}</div>`:''}${m.actions?`<div class="page-head-actions">${m.case_id?`<button class="outline-btn" data-action="office-note" data-caseid="${esc(m.case_id)}">Prepare office note</button><button class="outline-btn" data-action="verification">Draft verification request</button><button class="outline-btn" data-action="interim-reply" data-caseid="${esc(m.case_id)}">Draft factual interim reply</button><button class="outline-btn" data-action="task" data-caseid="${esc(m.case_id)}">Create follow-up task</button>`:''}<button class="outline-btn" data-action="knowledge">Open knowledge review</button></div>`:''}</div>`).join('')}${pending?'<div class="loading">Retrieving authorised records and calculating from the registry...</div>':''}</div><form class="composer followup" id="askForm"><textarea id="askInput" placeholder="Ask a follow-up or prepare an action..." aria-label="Ask a follow-up" required></textarea><div class="composer-foot"><span class="composer-note">Search &middot; Context &middot; Act</span><button class="primary-btn" type="submit" ${pending?'disabled':''}>Send &#8593;</button></div></form></div>`;
  }
  function appsView(){
    const modules=[['Pensions',data.pensions.length],['Grievances',data.grievances.length],['Work',data.tasks.length],['Projects','Unavailable'],['Documents',data.sources.length],['Approvals',data.approvals.length],['Knowledge',data.knowledge.length],['Forms','Unavailable'],['Analytics',data.stats.unresolved],['Meetings','Unavailable'],['Reports',data.documents.length],['Audit',47]];
    const productivity=['Google Drive','Google Docs','Google Sheets','Google Slides','Microsoft 365','Microsoft Teams','SharePoint','Outlook','Slack','Notion','GitHub'];
    const government=['Kritagyata','eOffice','CPGRAMS','NIC Email','Treasury','Service Book','Pension Registry','Office Records'];
    const other=['Local Database','File Server','Document Archive','Custom API','Spreadsheet Import','Departmental Software','Add application'];
    const tile=(n,group)=>`<article class="app-card" data-app-detail="${esc(n)}" data-app-group="${group}" role="button" tabindex="0"><div class="app-card-top"><span class="app-icon ${brandClass(n)}">${appGlyph(n,group)}</span><div><h3>${esc(n)}</h3><span class="quiet">${group==='Workspace'?'Available locally':'Not connected'}</span></div></div>${group==='Workspace'?'<div class="app-card-foot"><span class="classification">Workspace</span></div>':`<div class="app-card-foot"><span class="classification">${group}</span><button class="soft-btn" data-connect="${esc(n)}">Request access</button></div>`}</article>`;
    const head=`<div class="page-head"><div><div class="eyebrow">Pension & Public Grievances</div><h1 class="page-title">Apps</h1><p class="subhead">Department workspaces and applications available to this office.</p></div><div class="app-head-tools"><input class="input" id="appSearch" placeholder="Find an application..." aria-label="Find an application"><button class="outline-btn" id="requestsBtn">Requests ${data.connections.length?`(${data.connections.length})`:''}</button></div></div>`;
    if(appsFilter==='Requests')return `<div class="page">${head}<h2 class="section-label">Access requests</h2>${data.connections.length?data.connections.map(c=>`<div class="mini-row"><div><b>${esc(c.app||c.id)} / ${esc(c.status)}</b><small>${esc(c.purpose||'No purpose entered')} / ${esc(c.updated_at)}</small><small>External connection has not been verified.</small></div></div>`).join(''):'<div class="empty-state"><b>No access requests</b>Open an application and request access if required.</div>'}</div>`;
    return `<div class="page">${head}<section class="catalogue-section"><h2 class="section-label">Workspace applications</h2><div class="module-grid">${modules.map(([n,count])=>`<button class="module-card" data-module="${n}"><span class="app-icon">${icon(n)}</span><h3>${n}</h3><div class="module-count">${count==='Unavailable'?'Unavailable':`${count} records`}</div></button>`).join('')}</div></section><hr class="catalogue-divider"><section class="catalogue-section"><h2 class="section-label">Productivity applications</h2><div class="app-grid">${productivity.map(n=>tile(n,'Productivity')).join('')}</div></section><hr class="catalogue-divider"><section class="catalogue-section"><h2 class="section-label">Government applications</h2><div class="app-grid">${government.map(n=>tile(n,'Government')).join('')}</div></section><hr class="catalogue-divider"><section class="catalogue-section"><h2 class="section-label">Other applications</h2><div class="app-grid">${other.map(n=>tile(n,'Other')).join('')}</div></section><p class="quiet" style="margin-top:16px">External applications are not connected unless a verified status is shown.</p></div>`;
  }
  function brandClass(name){return ({'Google Docs':'app-google-docs','Google Sheets':'app-google-sheets','Google Slides':'app-google-slides','Google Drive':'app-google-drive','Microsoft 365':'app-microsoft','Microsoft Teams':'app-teams','Outlook':'app-outlook','SharePoint':'app-sharepoint'})[name]||''}
  function appGlyph(name,group){if(name==='Google Docs')return icon('Documents');if(name==='Google Sheets')return icon('Analytics');if(name==='Google Slides')return icon('Reports');if(name==='Google Drive')return icon('Files');if(name==='Microsoft Teams')return icon('People');if(name==='Outlook')return icon('Documents');if(name==='SharePoint')return icon('Apps');return icon(group==='Government'?'Government':group==='Productivity'?'Productivity':'Other')}
  function peopleView(){
    const tabs=['Directory','Organisation','Offices','Responsibilities','Workload','Relationships','Access'];
    return `<div class="page"><div class="page-head"><div><div class="eyebrow">Pension &amp; Public Grievances &middot; Assam</div><h1 class="page-title">People</h1><p class="subhead">Officers, offices, responsibilities and records within your access scope.</p></div><input class="input" id="peopleFilter" placeholder="Search people or offices..." aria-label="Search people or offices"></div><div class="tabs">${tabs.map((t,i)=>`<button class="tab ${i===0?'active':''}" data-people-tab="${t}">${t}</button>`).join('')}</div><div id="peopleContent">${peopleDirectory()}</div></div>`;
  }
  function peopleDirectory(){
    const offices=data.offices, office=id=>offices.find(o=>o.id===id)?.name||id||'Not recorded';
    return `<div class="panel table-wrap"><table class="data-table people-table"><thead><tr><th>Employee</th><th>Designation</th><th>Office</th><th>Responsibilities</th><th>Assigned work</th><th></th></tr></thead><tbody>${data.people.map(p=>{const cases=data.pensions.filter(x=>x.owner_id===p.id).length,tasks=data.tasks.filter(x=>x.assignee_id===p.id).length;return `<tr data-person-row><td><button class="person-link" data-person="${esc(p.id)}"><span class="avatar">${p.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><span><b>${esc(p.name)}</b><small>${esc(p.id)} / ${esc(p.role)}</small></span></button></td><td>${esc(p.designation)}</td><td>${esc(office(p.office_id))}</td><td>${esc(responsibility(p.role))}</td><td><b>${cases} cases</b><small>${tasks} tasks${cases===0&&tasks===0?' / none assigned':''}</small></td><td><button class="icon-button" data-person="${esc(p.id)}" aria-label="Open ${esc(p.name)}">...</button></td></tr>`}).join('')}</tbody></table></div><p class="quiet table-note">Counts use authorised workspace records. Some registry entries have no recorded owner; no assignments have been inferred.</p>`;
  }
  function responsibility(role){return ({leadership:'Department oversight and review',supervisor:'Section supervision and approvals',pension_assistant:'Pension case preparation',grievance_officer:'Grievance coordination',head_of_office:'Office review and case oversight',audit_officer:'Restricted audit review',system_admin:'Workspace administration',staff:'Department support',directorate_officer:'Directorate coordination'})[role]||'Not specified in supplied profiles'}
  function personCard(p,office){let owned=data.pensions.filter(x=>x.owner_id===p.id).length;let ts=data.tasks.filter(x=>x.assignee_id===p.id).length;return `<button class="person-card" data-person="${p.id}" style="text-align:left;background:white"><span class="avatar">${p.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.designation)}<br>${esc(office(p.office_id))}<br>${owned} assigned cases / ${ts} tasks</p></div></button>`}
  function organisationView(){
    const office=id=>data.offices.find(x=>x.id===id)?.name||id||'Department';
    const roots=data.people.filter(p=>!p.manager_id);
    const renderNode=p=>{const children=data.people.filter(x=>x.manager_id===p.id);return `<div class="org-person"><div class="org-person-head"><button class="org-toggle" data-org-toggle="${esc(p.id)}" ${children.length?'':'disabled'} aria-label="${children.length?'Collapse':'No reports'}">${children.length?'?':'?'}</button><button class="org-card" data-person="${esc(p.id)}"><span class="avatar">${p.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><span><b>${esc(p.name)}</b><small>${esc(p.designation)} ? ${esc(office(p.office_id))}</small></span></button></div>${children.length?`<div class="org-children" data-org-children="${esc(p.id)}">${children.map(renderNode).join('')}</div>`:''}</div>`};
    return `<div class="org-toolbar"><span class="quiet">Reporting lines from supplied officer profiles</span><div><button class="soft-btn" data-chart-zoom="out" aria-label="Zoom out">&#8722;</button> <button class="soft-btn" data-chart-zoom="reset">Reset</button> <button class="soft-btn" data-chart-zoom="in" aria-label="Zoom in">+</button></div></div><div class="org-viewport" id="orgViewport"><div class="org-chart" id="orgChart">${roots.map(renderNode).join('')||data.people.map(renderNode).join('')}</div></div><h2 class="section-label" style="margin-top:22px">Coordination offices</h2><div class="app-grid">${data.offices.filter(o=>['DEE','DOP','AG','TREASURY'].includes(o.id)).map(o=>`<div class="person-card office-card"><span class="app-icon">${icon('Government')}</span><div><h3>${esc(o.name)}</h3><p>${esc(o.location)} &middot; coordination relationship</p></div></div>`).join('')}</div>`;
  }
  function profileView(){const p=actor||{};return `<div class="page"><div class="eyebrow">Profile · Workspace profile</div><h1 class="page-title">${esc(p.name||'Officer')}</h1><p class="subhead">${esc(p.designation||'')} · ${esc(p.office_id||'')}</p><div class="panel" style="margin-top:20px"><div class="panel-head">Profile and security scope</div><div class="panel-body"><dl class="detail-list"><dt>Role</dt><dd>${esc(p.role)}</dd><dt>Workspace</dt><dd>Assam Pension & Public Grievances · workspace records</dd><dt>Classification</dt><dd><span class="classification">Synthetic records</span></dd><dt>Scope</dt><dd>Enforced by local server adapter on record retrieval and actions</dd><dt>Authentication</dt><dd>Local workspace session only; no production identity provider configured</dd><dt>Preferences</dt><dd>English · Light theme</dd></dl></div></div><div class="panel" style="margin-top:14px"><div class="panel-head">Responsibilities</div><div class="panel-body">${p.designation==='Pension Dealing Assistant'?'Prepare pension case summaries and verification requests; propose changes for Head of Office review.':esc(p.role)}. No official action is executed by this workspace.</div></div><div class="panel" style="margin-top:14px"><div class="panel-head">Access testing <span class="classification">Synthetic records</span></div><div class="panel-body">Switch between sample officer roles to review role-scoped behaviour. This role selector does not authenticate identity.<p><select class="select" id="personaSelect">${data.people.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)} · ${esc(x.role)}</option>`).join('')}</select> <button class="outline-btn" id="switchPersona">Use selected workspace profile</button></p></div></div><div style="margin-top:14px"><span class="quiet">Local sign-in and sign-out are unavailable; this is a workspace session.</span></div></div>`}
  function pensionsView(){let list=data.pensions.filter(p=>!searchText||JSON.stringify(p).toLowerCase().includes(searchText.toLowerCase()));if(selectedCase){let p=getCase(selectedCase);if(p)return pensionDetail(p)}return `<div class="page"><div class="page-head"><div><div class="eyebrow">Pensions · Training registry</div><h1 class="page-title">Pension proposals</h1><p class="subhead">${data.stats.pensions} fictional records · values are not payment or eligibility determinations.</p></div><button class="outline-btn" data-export="registry">Export XLSX</button></div><div class="filters"><input class="input" id="caseFilter" placeholder="Search name, proposal ID or district" value="${esc(searchText)}"><select id="stageFilter" class="select"><option value="">All stages</option>${[...new Set(data.pensions.map(p=>p.stage))].map(s=>`<option>${esc(s.replaceAll('_',' '))}</option>`).join('')}</select><select id="issueFilter" class="select"><option value="">All issue types</option>${[...new Set(data.pensions.map(p=>p.issue))].map(s=>`<option>${esc(s.replaceAll('_',' '))}</option>`).join('')}</select><span class="quiet">${list.length} shown</span></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Pensioner</th><th>Proposal ID</th><th>District</th><th>Issue</th><th>Stage</th><th>Owner</th><th>Registry</th></tr></thead><tbody>${list.slice(0,100).map(p=>`<tr><td><button class="text-link" data-case="${esc(p.id)}">${esc(p.pensioner_name)}</button></td><td>${esc(p.id)}</td><td>${esc(p.district)}</td><td>${esc(p.issue.replaceAll('_',' '))}</td><td>${esc(p.stage.replaceAll('_',' '))}</td><td>${esc(person(p.owner_id)?.name||'—')}</td><td>${p.unresolved?'Unresolved':'Other status'}</td></tr>`).join('')}</tbody></table></div></div>`}
  function pensionDetail(p){let docs=data.sources.filter(s=>s.proposal_id===p.id);let gs=data.grievances.filter(g=>g.proposal_id===p.id);return `<div class="page"><button class="soft-btn" data-back="pensions">← Pension registry</button><div class="page-head" style="margin-top:16px"><div><div class="eyebrow">${esc(p.case_id||p.id)} · ${esc(p.district)}</div><h1 class="page-title">${esc(p.pensioner_name)}</h1><p class="subhead">${esc(p.designation||'Pension proposal')} · ${esc(p.office_id)} · <span class="classification">TRAINING RECORD</span></p></div><div class="page-head-actions"><button class="outline-btn" data-case-ask="${esc(p.id)}">Ask about case</button><button class="outline-btn" data-action="verification" data-caseid="${esc(p.id)}">Draft verification request</button></div></div><div class="tabs">${['Overview','Service','Documents','Objections','Grievances','Timeline','Work','Approvals','Audit'].map(x=>`<button class="tab ${tab===x?'active':''}" data-case-tab="${x}">${x}</button>`).join('')}</div>${caseTab(p,docs,gs)}</div>`}
  function caseTab(p,docs,gs){if(tab==='Service')return `<div class="panel"><div class="panel-head">Service record</div><div class="panel-body"><dl class="detail-list"><dt>Appointment</dt><dd>${esc(p.appointment_date||'Not recorded')}</dd><dt>Retirement</dt><dd>${esc(p.retirement_date||'Not recorded')}</dd><dt>Claimed service</dt><dd>${p.claimed_service_months??'Not supplied'} months</dd><dt>Verified-record service</dt><dd>${p.verified_record_service_months??'Not supplied'} months</dd><dt>Leave interval</dt><dd>${esc(p.leave_start||'Not recorded')} to ${esc(p.leave_end||'Not recorded')}</dd><dt>Sanction order</dt><dd>${p.leave_sanction_order_available?'Available':'Not in supplied case records'}</dd></dl><div class="result-list">${docs.filter(d=>/^DOC-00[1-8]$/.test(d.id)).map(sourceRow).join('')}</div></div></div>`;if(tab==='Objections')return `<div class="panel"><div class="panel-head">Recorded objections and clarification</div><div class="panel-body">${docs.filter(d=>['DOC-006','DOC-007','DOC-008'].includes(d.id)).map(sourceRow).join('')||'No objection documents are linked in the supplied case records.'}<p class="quiet">The six-month difference is recorded for review. The available sources do not determine the legal treatment of extraordinary leave.</p></div></div>`;if(tab==='Documents')return `<div class="result-list">${docs.map(d=>sourceRow(d)).join('')}</div>`;if(tab==='Grievances')return `<div class="panel"><div class="panel-head">Linked grievance history</div><div class="panel-body">${gs.map(g=>`<div class="mini-row"><div><b>${esc(g.id)}</b><small>Received ${esc(g.received)} · ${g.status==='disposed'?`Administrative disposal ${esc(g.disposed)}`:'Open'} · outcome verified ${g.outcome_verified?'yes':'no'}</small></div></div>`).join('')||'No linked grievance records'}</div></div>`;if(tab==='Audit')return `<div class="panel"><div class="panel-head">Case access history</div><div class="panel-body">Restricted audit view. Use the Audit application under an authorised training role.</div></div>`;if(tab==='Work')return `<div class="panel"><div class="panel-head">Related tasks</div><div class="panel-body">${data.tasks.filter(t=>t.case_id===p.id).map(taskRow).join('')||'No related task has been created.'}<button class="outline-btn" data-action="task" data-caseid="${esc(p.id)}">＋ Create follow-up task</button></div></div>`;if(tab==='Approvals')return `<div class="panel"><div class="panel-head">Approval history</div><div class="panel-body">${data.approvals.filter(a=>a.target_id&&data.documents.find(d=>d.id===a.target_id)?.case_id===p.id).map(a=>`<div class="mini-row"><div><b>${esc(a.id)} · ${esc(a.state)}</b><small>Exact draft version ${a.target_version} · reviewer ${esc(person(a.reviewer_id)?.name||a.reviewer_id)}</small></div></div>`).join('')||'No approval activity.'}</div></div>`;if(tab==='Timeline')return `<div class="panel"><div class="panel-head">Case timeline</div><div class="panel-body">${docs.map(d=>`<div class="mini-row"><span class="mini-ico">◷</span><div><b>${esc(d.title)}</b><small>${esc(d.location)} · source version ${d.version}</small></div></div>`).join('')}</div></div>`;return `<div class="case-layout"><div class="panel"><div class="panel-head">Case overview</div><div class="panel-body"><dl class="detail-list"><dt>Recorded stage</dt><dd>${esc(p.stage.replaceAll('_',' '))}</dd><dt>Issue</dt><dd>${esc(p.issue.replaceAll('_',' '))}</dd><dt>Owner</dt><dd>${esc(person(p.owner_id)?.name||'—')} · ${esc(person(p.owner_id)?.designation||'')}</dd><dt>Retirement</dt><dd>${esc(p.retirement_date||'Not available')}</dd><dt>Proposal</dt><dd>${esc(p.id)}</dd><dt>Grievances</dt><dd>${gs.length?gs.map(g=>esc(g.id)).join(', '):'None linked'}</dd><dt>PPO status</dt><dd>${esc(p.ppo_status||'not established')}</dd><dt>Payment status</dt><dd>${esc(p.payment_status||'not established')}</dd></dl>${p.id==='PEN-NGN-2026-041'?`<div class="panel" style="margin-top:16px"><div class="panel-head">Service discrepancy</div><div class="panel-body">Claimed ${p.claimed_service_months} months · verified record ${p.verified_record_service_months} months · difference ${p.claimed_service_months-p.verified_record_service_months} months. Leave sanction order available: ${p.leave_sanction_order_available?'yes':'no'}. No legal treatment is determined here.</div></div>`:''}</div></div><div class="panel"><div class="panel-head">Evidence <span class="quiet">${docs.length} source records</span></div><div class="panel-body">${docs.slice(0,6).map(d=>sourceRow(d)).join('')}</div></div></div>`}
  function sourceRow(d){return `<div class="mini-row"><span class="mini-ico">▤</span><div><button class="text-link" data-source="${esc(d.id)}"><b>${esc(d.title)}</b></button><small>${esc(d.location)} · v${d.version} · ${esc(d.classification||'training')}</small><small>${esc(d.passage)}</small></div></div>`}
  function grievancesView(){return `<div class="page"><div class="eyebrow">Grievance management · Synthetic records</div><h1 class="page-title">Public grievances</h1><p class="subhead">Administrative disposal is shown separately from substantive resolution.</p><div class="panel table-wrap" style="margin-top:18px"><table class="data-table"><thead><tr><th>Grievance</th><th>Proposal</th><th>Received</th><th>Status</th><th>Disposal</th><th>Outcome verified</th><th>Owner</th></tr></thead><tbody>${data.grievances.map(g=>`<tr><td><button class="text-link" data-case="${esc(g.proposal_id)}">${esc(g.id)}</button></td><td>${esc(g.proposal_id)}</td><td>${esc(g.received)}</td><td>${statusPill(g.status)}</td><td>${esc(g.disposed||'—')}</td><td>${g.outcome_verified?'Yes':'No'}</td><td>${esc(person(g.owner_id)?.name||'—')}</td></tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:15px"><div class="panel-head">Prepare a review recommendation</div><div class="panel-body">A draft recommendation can be prepared and routed for review. No complaint status is changed automatically.<p><button class="outline-btn" data-action="grievance-review" data-caseid="PEN-NGN-2026-041">Prepare linked grievance review</button></p></div></div></div>`}
  function filesView(){return `<div class="page"><div class="page-head"><div><div class="eyebrow">Evidence library</div><h1 class="page-title">Files</h1><p class="subhead">Imported source records are immutable training originals with version metadata and source hashes.</p></div></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Document</th><th>Location</th><th>Version</th><th>Classification</th><th>Integrity</th></tr></thead><tbody>${data.sources.map(d=>`<tr><td>${esc(d.id)}</td><td><button class="text-link" data-source="${esc(d.id)}">${esc(d.title)}</button></td><td>${esc(d.location)}</td><td>${d.version}</td><td>${esc(d.classification)}</td><td>${d.sha256?'SHA-256 indexed':'Unavailable'}</td></tr>`).join('')}</tbody></table></div><p class="quiet" style="margin-top:12px">These are Markdown source passages, not original government PDFs. Logical source locations do not claim generated-PDF page numbers.</p></div>`}
  function knowledgeView(){return `<div class="page"><div class="eyebrow">Knowledge governance</div><h1 class="page-title">Knowledge changes</h1><p class="subhead">Proposed clarification remains unverified and unpublished. Governing official pension rules and their operative versions were not imported or verified, so no authoritative rule comparison is claimed.</p>${data.knowledge.map(k=>{let d=JSON.parse(k.data);return `<div class="panel" style="margin-top:16px"><div class="panel-head">${esc(k.id)} ${statusPill(k.state)}</div><div class="panel-body"><dl class="detail-list"><dt>Source</dt><dd><button class="text-link" data-source="${esc(d.source_id)}">${esc(d.source_id)} · ${esc(source(d.source_id)?.title||'')}</button></dd><dt>Requester</dt><dd>${esc(person(d.requester_id)?.name||d.requester_id)}</dd><dt>Reviewer</dt><dd>${esc(person(d.reviewer_id)?.name||d.reviewer_id)}</dd><dt>Potential matches</dt><dd>${d.potential_case_ids.length} cases · ${d.manual_review_case_ids.length} manual review</dd><dt>Authority</dt><dd>${d.authority_verified?'Verified':'Not verified'}</dd><dt>Signature</dt><dd>${d.signature_verified?'Verified':'Not verified'}</dd><dt>Effective date</dt><dd>${d.effective_date_verified?'Verified':'Not verified'}</dd><dt>Rule compatibility</dt><dd>${d.rule_compatibility_verified?'Verified':'Not verified'}</dd><dt>Publication approval</dt><dd>${d.publication_approved?'Approved':'Pending'}</dd></dl><p><button class="outline-btn" data-action="knowledge">Prepare evidence review note</button></p><span class="quiet">Publication is blocked until source authority, signature, date, compatibility and review are verified.</span></div></div>`}).join('')}</div>`}
  function approvalsView(){const docs=(data.approvals||[]).map(a=>{let d=data.documents.find(x=>x.id===a.target_id);return `<div class="mini-row"><div style="flex:1"><b>${esc(d?.title||a.target_id)} · ${esc(a.id)}</b><small>Draft v${a.target_version} · reviewer ${esc(person(a.reviewer_id)?.name||a.reviewer_id)} · submitted ${esc(a.created_at)}</small><small>Status: ${statusPill(a.state)} ${a.reason?esc(a.reason):''}</small>${a.state==='submitted'&&a.reviewer_id===actor?.id&&a.created_by!==actor?.id?`<div style="display:flex;gap:7px;margin-top:8px"><button class="primary-btn" data-decision="approved" data-approval="${a.id}">Approve training draft</button><button class="outline-btn" data-decision="returned" data-approval="${a.id}">Return</button><button class="danger-btn" data-decision="rejected" data-approval="${a.id}">Reject</button></div>`:''}</div></div>`}).join('');const changes=(data.case_proposals||[]).map(p=>{const a=data.approvals.find(x=>x.target_id===p.id&&x.target_version===p.version&&x.state==='submitted');return `<div class="mini-row"><div style="flex:1"><b>Proposed change ${esc(p.id)} · ${esc(p.case_id)}</b><small>${esc(p.field.replaceAll('_',' '))}: ${esc(p.previous_value)} → ${esc(p.proposed_value)} · source ${esc(p.source_id)}</small><small>Version ${p.version} · requester ${esc(person(p.requester_id)?.name||p.requester_id)} · ${statusPill(p.state)}</small>${a&&p.reviewer_id===actor?.id&&p.requester_id!==actor?.id?`<div style="display:flex;gap:7px;margin-top:8px"><button class="primary-btn" data-decision="approved" data-approval="${a.id}">Approve proposed change</button><button class="outline-btn" data-decision="returned" data-approval="${a.id}">Return for revision</button><button class="danger-btn" data-decision="rejected" data-approval="${a.id}">Reject proposal</button></div>`:''}${['returned','rejected'].includes(p.state)&&actor?.id===p.requester_id?`<div style="margin-top:8px"><button class="outline-btn" data-revise="${esc(p.id)}">Revise as version ${p.version+1}</button></div>`:''}${p.state==='approved'&&!['P06',p.requester_id,p.reviewer_id].includes(actor?.id)&&['supervisor','leadership','head_of_office'].includes(actor?.role)?`<div style="margin-top:8px"><button class="primary-btn" data-execute="${esc(p.id)}">Execute approved change</button></div>`:''}${p.state==='executed'?'<small>Executed as a separate authorised step. Earlier case versions remain preserved.</small>':''}</div></div>`}).join('');return `<div class="page"><div class="eyebrow">Review queue</div><h1 class="page-title">Approvals</h1><p class="subhead">Each decision binds to an immutable saved draft or proposed-change version. Approval and execution are separate steps.</p><div class="panel" style="margin-top:18px"><div class="panel-head">Pending and decided reviews</div><div class="panel-body">${changes}${docs||'<div class="empty-state"><b>No document review requests yet</b>Create a draft from Search and submit it for review.</div>'}<div class="quiet" style="margin-top:14px">${(data.approval_events||[]).length} approval history events retained.</div></div></div></div>`}
  function taskRow(t){const canEdit=actor?.id===t.assignee_id||['leadership','supervisor','head_of_office'].includes(actor?.role);return `<div class="mini-row"><span class="mini-ico">☷</span><div style="flex:1"><b>${esc(t.title)}</b><small>${esc(t.case_id||'Workspace task')} · ${esc(person(t.assignee_id)?.name||t.assignee_id)} · due ${esc(t.due_date||'not set')} · ${statusPill(t.status)}</small>${canEdit?`<select class="select" data-task-status="${esc(t.id)}" aria-label="Update task status" style="margin-top:6px"><option value="prepared" ${t.status==='prepared'?'selected':''}>Prepared</option><option value="in_progress" ${t.status==='in_progress'?'selected':''}>In progress</option><option value="submitted_for_review" ${t.status==='submitted_for_review'?'selected':''}>Submit for review</option><option value="completed" ${t.status==='completed'?'selected':''}>Completed</option><option value="returned" ${t.status==='returned'?'selected':''}>Returned</option></select>`:''}</div></div>`}
  function workView(){return `<div class="page"><div class="page-head"><div><div class="eyebrow">Operational work</div><h1 class="page-title">Work</h1><p class="subhead">Prepared tasks and follow-ups from pension, grievance and document workflows.</p></div><button class="primary-btn" data-action="task">＋ New task</button></div><div class="panel"><div class="panel-head">Tasks <span class="quiet">${data.tasks.length} records</span></div><div class="panel-body">${data.tasks.map(taskRow).join('')||'<div class="empty-state">No tasks saved yet.</div>'}</div></div></div>`}
  function analyticsView(){let unresolved=data.pensions.filter(p=>p.unresolved), counts={};for(const p of unresolved)counts[p.issue]=(counts[p.issue]||0)+1;return `<div class="page"><div class="eyebrow">Registry analysis</div><h1 class="page-title">Analytics</h1><p class="subhead">Counts calculated from the current local registry as of 24 November 2026.</p><div class="panel" style="margin-top:18px"><div class="panel-head">Unresolved pension proposals</div><div class="panel-body"><table class="result-table"><thead><tr><th>Measure</th><th>Count</th></tr></thead><tbody><tr><td>All registry records</td><td>${data.pensions.length}</td></tr><tr><td>Unresolved</td><td>${unresolved.length}</td></tr><tr><td>Head of Office stage among unresolved</td><td>${unresolved.filter(p=>p.stage==='head_of_office').length}</td></tr>${Object.entries(counts).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${v}</td></tr>`).join('')}</tbody></table><button class="outline-btn" data-export="registry">Download XLSX</button> <button class="outline-btn" data-report="cohort">Generate DOCX report</button></div></div><p class="quiet">Counts are derived from fixture records. Current changes and baseline fixture counts can be compared through audit history.</p></div>`}
  async function auditView(){try{const a=await api('/api/audit');data.audit=a;return auditTable(a)}catch(e){return `<div class="page"><h1 class="page-title">Audit</h1><p class="subhead">${esc(e.message)}</p></div>`}}
  function auditTable(a){let items=a.items||[];let denied=items.filter(x=>['denied','blocked'].includes(x.decision)).length;return `<div class="page"><div class="page-head"><div><div class="eyebrow">Restricted · authorised reviewers only</div><h1 class="page-title">Audit trail</h1><p class="subhead">Supplied source log · ${items.length} recorded events · ${denied} denied or blocked · append-only local action events below.</p></div><button class="outline-btn" data-report="security">Prepare security review</button></div><div class="panel table-wrap" style="margin-top:18px"><table class="data-table"><thead><tr><th>Timestamp</th><th>Actor</th><th>Event</th><th>Decision</th><th>Record</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.timestamp)}</td><td>${esc(person(x.actor_id)?.name||x.actor_id)}</td><td>${esc(x.action)}</td><td>${statusPill(x.decision)}</td><td>${esc(x.proposal_id||x.id)}</td></tr>`).join('')}</tbody></table></div><h2 class="section-label" style="margin-top:18px">Workspace actions <span class="quiet">${a.actions.length} events</span></h2>${a.actions.map(x=>`<div class="mini-row"><div><b>${esc(x.action)} · ${esc(x.outcome)}</b><small>${esc(x.created_at)} · ${esc(x.actor_id)} · ${esc(x.resource_id)}</small></div></div>`).join('')}</div>`}
  function reportsView(){return `<div class="page"><div class="eyebrow">Document outputs</div><h1 class="page-title">Reports</h1><p class="subhead">Generated files are saved as versioned drafts. A revision creates a new version and new review request.</p><div class="panel" style="margin-top:16px"><div class="panel-head">Saved documents <span class="quiet">${data.documents.length}</span></div><div class="panel-body">${data.documents.map(d=>`<div class="mini-row"><div style="flex:1"><b>${esc(d.title)}</b><small>${esc(d.id)} ? version ${d.version} ? ${statusPill(d.status)} ? ${esc(d.created_at)}</small></div>${d.created_by===actor?.id||['leadership','supervisor'].includes(actor?.role)?`<button class="soft-btn" data-revise-document="${esc(d.id)}">Revise</button>`:''}${['docx','pdf','xlsx','pptx'].map(f=>`<a class="soft-btn" href="/api/download/${d.id}?format=${f}">${f.toUpperCase()}</a>`).join('')}</div>`).join('')||'<div class="empty-state">No generated reports saved yet.</div>'}</div></div></div>`}
  function moduleStub(n,desc){return `<div class="page"><button class="soft-btn" data-back="apps">← Apps</button><div class="eyebrow">Department workspace</div><h1 class="page-title">${esc(n)}</h1><p class="subhead">${esc(desc)}</p><div class="panel" style="margin-top:18px"><div class="panel-body">This section uses the workspace records. External government operations are unavailable.</div></div></div>`}
  function wire(){
    document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>nav(b.dataset.route));
    document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const n=b.dataset.module.toLowerCase();nav(n==='work'?'work':n==='audit'?'audit':n==='analytics'?'analytics':n==='reports'?'reports':n==='approvals'?'approvals':n==='knowledge'?'knowledge':n==='grievances'?'grievances':n==='pensions'?'pensions':n==='documents'?'files':n==='files'?'files':n==='meetings'?'meetings':n==='projects'?'projects':n==='forms'?'forms':'apps')});
    document.querySelectorAll('[data-appfilter]').forEach(b=>b.onclick=()=>{appsFilter=b.dataset.appfilter;render()});
    $('#requestsBtn')?.addEventListener('click',()=>{appsFilter='Requests';render()});$('#appSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.app-card,.module-card').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))});
    $('#attachBtn')?.addEventListener('click',()=>toast('File attachment import is unavailable in this workspace.'));
    $('#voiceBtn')?.addEventListener('click',()=>toast('Voice input is unavailable in this workspace.'));
    $('#sourceSelect')?.addEventListener('click',()=>toast('Search uses records available to your current workspace role.'));
    $('#askForm')?.addEventListener('submit',async e=>{e.preventDefault();const q=$('#askInput').value.trim();if(!q||pending)return;if(Array.isArray(conversation))conversation={title:q.slice(0,62),messages:[]};conversation.title=conversation.title||q.slice(0,62);conversation.messages.push({role:'user',body:q});pending=true;render();try{await persistMessage('user',q);const r=await api('/api/ask',{method:'POST',body:JSON.stringify({query:q,tool:'search_records'})});selectedCase=r.case_id||selectedCase;conversation.messages.push({role:'assistant',...r,actions:true});await persistMessage('assistant',JSON.stringify(r),r.citations||[])}catch(err){conversation.messages.push({role:'assistant',body:err.message,citations:[]})}pending=false;await refresh();render();document.querySelector('.messages')?.scrollTo(0,99999);});
    document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.suggest),s=suggestionQueries[i];conversation={title:s.slice(0,62),messages:[]};conversationId=null;submitQuery(s,'search_records')});
    $('#newChat')?.addEventListener('click',()=>{conversation=[];conversationId=null;render()});$('#historyBtn')?.addEventListener('click',showHistory);
    document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.source));
    document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>nav('pensions',b.dataset.case));
    document.querySelectorAll('[data-case-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.caseTab;render()});
    document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>nav(b.dataset.back));
    document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionModal(b.dataset.action,b.dataset.caseid||selectedCase));
    document.querySelectorAll('[data-task-status]').forEach(s=>s.onchange=async()=>{try{await api(`/api/task/${s.dataset.taskStatus}`,{method:'PATCH',body:JSON.stringify({status:s.value})});toast('Task status saved.');await refresh();render()}catch(e){toast(e.message)}});
    document.querySelectorAll('[data-case-ask]').forEach(b=>b.onclick=()=>{conversation=[];conversationId=null;nav('search');submitQuery(`Summarize case ${b.dataset.caseAsk}`,'review_case')});
    document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>decision(b.dataset.approval,b.dataset.decision));
    document.querySelectorAll('[data-execute]').forEach(b=>b.onclick=()=>executeProposal(b.dataset.execute));
    document.querySelectorAll('[data-revise]').forEach(b=>b.onclick=()=>reviseProposal(b.dataset.revise));
    document.querySelectorAll('[data-revise-document]').forEach(b=>b.onclick=()=>reviseDocument(b.dataset.reviseDocument));
    document.querySelectorAll('[data-connect]').forEach(b=>b.onclick=e=>{e.stopPropagation();$('#modalRoot').innerHTML='';connect(b.dataset.connect)});document.querySelectorAll('[data-app-detail]').forEach(b=>{b.onclick=e=>{if(!e.target.closest('[data-connect]'))openApp(b.dataset.appDetail,b.dataset.appGroup)};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openApp(b.dataset.appDetail,b.dataset.appGroup)}}});
    document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>downloadExport(b.dataset.export));
    document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>createReport(b.dataset.report));
    $('#profileOpen')?.addEventListener('click',()=>nav('profile'));$('#helpBtn')?.addEventListener('click',showAbout);$('#notifyBtn')?.addEventListener('click',()=>toast('No pending notifications in this workspace session.'));
    $('#collapse')?.addEventListener('click',()=>{$('#sidebar').classList.toggle('collapsed');$('#main').classList.toggle('collapsed')});
    $('#caseFilter')?.addEventListener('input',e=>{searchText=e.target.value;const y=window.scrollY;render();window.scrollTo(0,y)});
    $('#stageFilter')?.addEventListener('change',applyCaseFilters);$('#issueFilter')?.addEventListener('change',applyCaseFilters);
    $('#peopleFilter')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-person-row]').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))});
    document.querySelectorAll('[data-people-tab]').forEach(b=>b.onclick=()=>peopleTab(b.dataset.peopleTab));document.querySelectorAll('[data-chart-zoom]').forEach(b=>b.onclick=()=>{chartScale=b.dataset.chartZoom==='reset'?1:Math.max(.7,Math.min(1.5,chartScale+(b.dataset.chartZoom==='in'?.1:-.1)));const chart=$('#orgChart');if(chart)chart.style.transform=`scale(${chartScale})`});document.querySelectorAll('[data-org-toggle]').forEach(b=>b.onclick=()=>{const child=document.querySelector(`[data-org-children="${b.dataset.orgToggle}"]`);if(child){child.hidden=!child.hidden;b.textContent=child.hidden?'+':'&#8722;'}});
    document.querySelectorAll('[data-person]').forEach(b=>{b.onclick=()=>personProfile(b.dataset.person);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();personProfile(b.dataset.person)}}});const org=$('#orgViewport');if(org){let drag=null;org.onpointerdown=e=>{if(e.target.closest('[data-person],[data-org-toggle]'))return;drag=[e.clientX,e.clientY,org.scrollLeft,org.scrollTop];org.setPointerCapture(e.pointerId)};org.onpointermove=e=>{if(drag){org.scrollLeft=drag[2]-(e.clientX-drag[0]);org.scrollTop=drag[3]-(e.clientY-drag[1])}};org.onpointerup=()=>drag=null}
    $('#switchPersona')?.addEventListener('click',async()=>{try{let s=await api('/api/actor',{method:'POST',body:JSON.stringify({person_id:$('#personaSelect').value})});actor=s.actor;toast(`Workspace profile: ${actor.name}`);render()}catch(e){toast(e.message)}});
  }
  async function refresh(){try{data=await api('/api/bootstrap');}catch(e){toast(e.message)}}
  async function persistMessage(role,body,citations=[]){if(!conversationId){let c=await api('/api/conversations',{method:'POST',body:JSON.stringify({title:conversation.title||'New conversation'})});conversationId=c.id}await api(`/api/conversations/${conversationId}/messages`,{method:'POST',body:JSON.stringify({role,body,citations})})}
  async function submitQuery(q,tool='search_records'){if(Array.isArray(conversation))conversation={title:q.slice(0,62),messages:[]};conversation.title=conversation.title||q.slice(0,62);conversation.messages.push({role:'user',body:q});pending=true;nav('search');try{await persistMessage('user',q);let r=await api('/api/ask',{method:'POST',body:JSON.stringify({query:q,tool})});selectedCase=r.case_id||selectedCase;conversation.messages.push({role:'assistant',...r,actions:true});await persistMessage('assistant',JSON.stringify(r),r.citations||[])}catch(e){conversation.messages.push({role:'assistant',body:e.message})}pending=false;await refresh();render()}
  async function openSource(id){try{let d=await api(`/api/source/${encodeURIComponent(id)}`);openDrawer(d.title,`${d.location} ? Version ${d.version}`,`<div class="source-detail"><div class="source-meta"><span class="chip">${esc(d.classification||'Synthetic records')}</span><span>${esc(d.id)}</span></div><div class="source-passage"><div class="eyebrow">Supporting passage ? ${esc(d.anchor||d.location)}</div><p>${esc(d.passage||'No excerpt recorded.')}</p></div><details><summary>Open source record</summary><pre>${esc(d.content||'')}</pre></details><div class="source-hash"><small>SHA-256</small><code>${esc(d.sha256)}</code></div></div>`)}catch(e){toast(e.message)}}
  function openDrawer(title,sub,body){const root=$('#modalRoot');root.innerHTML=`<div class="drawer-backdrop" id="drawerBackdrop"><aside class="side-drawer" role="dialog" aria-modal="true"><header class="drawer-head"><div><h2>${esc(title)}</h2><p>${esc(sub||'')}</p></div><button class="icon-button" id="closeDrawer" aria-label="Close panel">?</button></header><div class="drawer-content">${body}</div></aside></div>`;$('#closeDrawer').onclick=()=>root.innerHTML='';$('#drawerBackdrop').onclick=e=>{if(e.target.id==='drawerBackdrop')root.innerHTML=''};document.addEventListener('keydown',function closeOnEscape(e){if(e.key==='Escape'){root.innerHTML='';document.removeEventListener('keydown',closeOnEscape)}})}

  function showModal(title,sub,body,actions=''){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="icon-button" id="closeModal" aria-label="Close">×</button></div><div class="modal-content">${esc(body)}</div>${actions?`<div class="modal-head">${actions}</div>`:''}</section></div>`;$('#closeModal').onclick=()=>root.innerHTML='';$('#backdrop').onclick=e=>{if(e.target.id==='backdrop')root.innerHTML=''}}
  function actionModal(kind,caseId){const p=getCase(caseId)||getCase('PEN-NGN-2026-041');const isTask=kind==='task';const title=kind==='office-note'?`Office note - ${p?.id||'Pension case'}`:kind==='verification'?'Service verification request':kind==='interim-reply'?'Factual interim grievance reply':kind==='grievance-review'?'Grievance review recommendation':kind==='knowledge'?'Knowledge evidence review':isTask?'Follow-up task':'Case note';const body=kind==='office-note'?`OFFICE NOTE ? ${p?.case_id||p?.id||'Pension proposal'}\n\nSubject: Status and pending verification\n\nThe supplied case record identifies ${p?.pensioner_name||'the pensioner'} of ${p?.district||'the district'}. Current recorded stage: ${String(p?.stage||'not specified').replaceAll('_',' ')}. Claimed service: ${p?.claimed_service_months??'not recorded'} months; verified-record service: ${p?.verified_record_service_months??'not recorded'} months. Arithmetic difference: ${(p?.claimed_service_months||0)-(p?.verified_record_service_months||0)} months.\n\nThe available records do not establish the legal treatment of the service discrepancy or confirm PPO issue/payment. Obtain and verify the supporting service book and leave sanction records before further determination.\n\nPrepared for review; not an official decision or dispatch.\nSources: ${data.sources.filter(d=>d.proposal_id===p?.id).map(d=>d.id).join(', ')||'No case-linked source is available in the current scope.'}.`:kind==='verification'?`To: Head of Office, ${p?.office_id||'DEEO-NGN'}\nSubject: Verify qualifying-service discrepancy — ${p?.id||'PEN-NGN-2026-041'}\n\nPlease provide the leave sanction order and a verified statement addressing the recorded service figures. The supplied record notes claimed service of 388 months and a verified record of 382 months, with extraordinary leave from July through December 2004. The current training record does not establish the legal treatment of that period. Please review the original service book and applicable authoritative rules.\n\nPrepared for review only. No official dispatch is made.\nSource: DOC-002, DOC-003, DOC-004, DOC-006 and DOC-009.`:kind==='interim-reply'?`Subject: Update on your pension grievance ? ${p?.id||'PEN-NGN-2026-041'}\n\nYour grievance remains under consideration. The records available in this workspace show that a proposal was at the Head of Office stage on 24 November 2026 and that service verification and supporting records require clarification. We cannot confirm from the records reviewed that a PPO has been issued or payment has been made. The department is seeking an updated case-specific status and will review the supporting documents before communicating a decision.\n\nThis is a factual draft for authorised review only. It does not dispose of the grievance, determine pension eligibility, or constitute dispatch.\nSources: DOC-009, DOC-011 and DOC-012.`:kind==='grievance-review'?`Recommendation: Review the administrative disposal recorded for GRV-AS-2026-01192 against the current proposal status and the open GRV-AS-2026-01874. The 22 September action-taken report describes processing for early settlement; the 24 November record does not establish forwarding, PPO issuance or payment. Request a current case-specific status and supporting evidence. Do not reopen or change grievance status without authorised review.\nSources: DOC-009, DOC-010, DOC-011, DOC-012.`:kind==='knowledge'?`Evidence review for proposed knowledge change KB-CHANGE-2026-0037. The 20 November clarification is an unverified training record. Issuing authority, signature, effective date and compatibility with the Assam Services (Pension) Rules, 1969 remain unverified. Seven potential case matches are listed and one case requires manual review. Publication remains blocked pending competent verification and approval.\nSource: DOC-017 and DOC-018.`:isTask?'':`Training review note based on the retrieved source records. Verify the cited passages before relying on this summary. No official determination is made.`;
    if(isTask){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal"><div class="modal-head"><div><h2>Create a follow-up task</h2><p>Prepared in the local workspace</p></div><button class="icon-button" id="closeModal">×</button></div><div class="modal-content"><form id="taskForm"><label>Task title<br><input class="input" name="title" required value="Obtain verified service statement and leave sanction order"></label><p>Related proposal <b>${esc(p?.id||'Workspace')}</b></p><label>Assignee<br><select class="select" name="assignee">${data.people.filter(x=>['P09','P06','P05'].includes(x.id)).map(x=>`<option value="${x.id}" ${x.id===actor.id?'selected':''}>${esc(x.name)} · ${esc(x.designation)}</option>`).join('')}</select></label><p><label>Due date<br><input class="input" name="due" type="date"></label></p><button class="primary-btn">Save prepared task</button></form></div></section></div>`;$('#closeModal').onclick=()=>$('#modalRoot').innerHTML='';$('#taskForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/task',{method:'POST',body:JSON.stringify({title:f.get('title'),assignee_id:f.get('assignee'),due_date:f.get('due'),case_id:p?.id})});$('#modalRoot').innerHTML='';toast('Task saved as prepared.');await refresh();nav('work')}catch(err){toast(err.message)}};return}
    const actions=`<button class="primary-btn" id="saveDraft">Save as version 1 draft</button>`;showModal(title,'Prepared draft · Synthetic training data',body,actions);$('#saveDraft').onclick=async()=>{try{const d=await api('/api/document',{method:'POST',body:JSON.stringify({title,kind,case_id:p?.id||null,content:body})});const a=await api('/api/approval',{method:'POST',body:JSON.stringify({target_id:d.id,version:d.version,reviewer_id:'P09'})});toast(`Draft ${d.id} saved and submitted as v${d.version}. Awaiting review ${a.id}.`);$('#modalRoot').innerHTML='';await refresh();nav('approvals')}catch(e){toast(e.message)}}
  }
  async function decision(id,decision){const reason=prompt(`Reason for ${decision} (required for workspace audit):`);if(reason===null)return;try{await api(`/api/approval/${id}`,{method:'POST',body:JSON.stringify({decision,reason})});toast(`Review recorded: ${decision}.`);await refresh();render()}catch(e){toast(e.message)}}
  async function reviseProposal(id){const p=(data.case_proposals||[]).find(x=>x.id===id);if(!p)return;const value=prompt('Proposed verification status for the new version:',p.proposed_value);if(value===null)return;try{const r=await api(`/api/case-proposal/${id}/revise`,{method:'POST',body:JSON.stringify({proposed_value:value})});const a=await api('/api/approval',{method:'POST',body:JSON.stringify({target_id:id,version:r.version})});toast(`Version ${r.version} prepared. New approval ${a.id} submitted.`);await refresh();render()}catch(e){toast(e.message)}}
  async function executeProposal(id){if(!confirm('Execute this separately approved change? The operation will update only the synthetic local record and create a new case version.'))return;try{await api(`/api/case-proposal/${id}/execute`,{method:'POST',body:JSON.stringify({})});toast('Approved change executed in the workspace database.');await refresh();render()}catch(e){toast(e.message)}}
  async function reviseDocument(id){try{const d=await api(`/api/document/${id}`);const content=prompt('Edit the draft contents. Saving creates a new immutable version.',d.content);if(content===null)return;const r=await api(`/api/document/${id}`,{method:'PATCH',body:JSON.stringify({base_version:d.version,content})});let reviewer=d.case_id?(getCase(d.case_id)?.owner_id||'P09'):'P01';if(reviewer===actor.id)reviewer=actor.role==='leadership'?'P02':'P09';const a=await api('/api/approval',{method:'POST',body:JSON.stringify({target_id:id,version:r.version,reviewer_id:reviewer})});toast(`Version ${r.version} saved and submitted for review (${a.id}).`);await refresh();render()}catch(e){toast(e.message)}}
  function openApp(name,group){const connected=!!data.connections.find(x=>x.app===name&&x.status==='connected');const native=['Pensions','Grievances','Documents','Approvals','Work','Knowledge','Analytics','Audit','Reports'].includes(name);let details=native?({Pensions:'Pension proposal registry and case timelines',Grievances:'Linked complaints and response drafts',Documents:'Indexed sources, versions and generated files',Approvals:'Version-bound review queue',Work:'Assigned tasks and follow-ups',Knowledge:'Source verification and change impact',Analytics:'Calculated registry summaries',Audit:'Restricted access and event history',Reports:'Generated departmental documents'})[name]:'No live connection is configured for this application.';openDrawer(name,group,`<div class="app-detail"><div class="app-detail-mark">${icon(group)}</div><p>${esc(details||'Application available for configuration.')}</p><dl class="detail-list"><dt>Connection</dt><dd>${native?'Available in workspace':connected?'Connected':'Not connected'}</dd><dt>Available data</dt><dd>${native?'Authorised records in this workspace':'Not synchronised'}</dd><dt>Permissions</dt><dd>${native?'Current officer scope and role permissions':'No external permissions configured'}</dd><dt>Last synchronisation</dt><dd>${native?'Live local query':'None'}</dd></dl>${native?`<button class="primary-btn" data-open-module="${esc(name)}">Open ${esc(name)}</button>`:`<p class="quiet">Connection and access have not been verified.</p><button class="outline-btn" data-connect="${esc(name)}">Request access</button><button class="soft-btn" data-connect="${esc(name)}">Configure connection</button>`}</div>`);document.querySelector('[data-open-module]')?.addEventListener('click',()=>{const n=name.toLowerCase();nav(({documents:'files'}[n]||n));$('#modalRoot').innerHTML=''})}
  async function connect(app){const purpose=prompt(`Why do you need access to ${app}?`);if(!purpose)return;try{const r=await api('/api/connection/request',{method:'POST',body:JSON.stringify({app,purpose})});toast(`Request saved (${r.id}). Live connection remains unavailable.`);await refresh()}catch(e){toast(e.message)}}
  async function downloadExport(type){try{if(type==='registry'){location.href='/api/download/export-registry?format=xlsx';return}}catch(e){toast(e.message)}}
  async function createReport(kind){let title,content,caseId=null;const all=data.pensions,un=all.filter(p=>p.unresolved);if(kind==='security'){const ev=data.audit?.items||[];const den=ev.filter(x=>['denied','blocked'].includes(x.decision));const actors=new Set(ev.filter(x=>x.decision==='allowed').map(x=>x.actor_id));const le=ev.filter(x=>x.external_disclosure_confirmed).length;title='SEC-REV-2026-0041 · Access review';caseId='PEN-NGN-2026-041';content=`Security review of the supplied access logs for PEN-NGN-2026-041 since 1 August 2026.\n\nEvents reviewed: ${ev.length}. Distinct authorised actors in allowed events: ${actors.size}. Denied or blocked operations: ${den.length}. Confirmed successful external disclosures in these logs: ${le}.\n\nTwo events require context review: 22 November 2026 at 14:16, an unrelated-branch service book request was denied; 23 November 2026 at 09:31, an external export request was blocked. A denied or blocked event does not establish intent. No successful external disclosure appears in the reviewed records; this does not exclude activity outside the logs. Preserve records and request the appropriate access justification.\n\nSources: DOC-015, DOC-016 and audit fixture events AUD-CASE-046/047. SYNTHETIC RECORDS — NOT AN OFFICIAL GOVERNMENT DOCUMENT.`}else if(kind==='knowledge'){title='Knowledge change evidence review · KB-CHANGE-2026-0037';content='The 20 November supplied clarification is indexed but unverified. Issuing authority, signature, effective date and rule compatibility remain unverified. Seven potential case matches are listed in the supplied knowledge change fixture; Hemanta Kumar Nath requires manual review. No knowledge publication or pension case change has occurred. Sources: DOC-017 and DOC-018. SYNTHETIC RECORDS — NOT AN OFFICIAL GOVERNMENT DOCUMENT.'}else{const counts={};for(const p of un)counts[p.issue]=(counts[p.issue]||0)+1;title='Nagaon unresolved pension cohort review';content=`Registry review as of 24 November 2026. ${all.length} pension records are present in the supplied registry; ${un.length} are unresolved, including ${un.filter(p=>p.stage==='head_of_office').length} at Head of Office stage. Issue categories: service verification ${counts.service_verification||0}; missing documents ${counts.missing_documents||0}; clarification ${counts.clarification||0}; other ${counts.other||0}. Eleven service-verification objections were raised after retirement; seven were visible before retirement. These are record counts and a descriptive observation, not a legal eligibility determination.\n\nCase-wise annexure:\n${un.map(p=>`${p.id} · ${p.pensioner_name} · ${p.district} · ${p.issue} · ${p.stage}`).join('\n')}\n\nSource: DOC-013 and linked case records. SYNTHETIC RECORDS — NOT AN OFFICIAL GOVERNMENT DOCUMENT.`}try{const d=await api('/api/document',{method:'POST',body:JSON.stringify({title,kind:`${kind}-report`,case_id:caseId,content})});toast(`Report saved as ${d.id}, version ${d.version}.`);await refresh();nav('reports')}catch(e){toast(e.message)}}
  async function showHistory(){try{const h=await api('/api/conversations');const rows=h.items.map(x=>`<div class="history-item"><button class="text-link" data-history="${x.id}">${esc(x.title)}</button><small>${esc(x.updated_at)}</small></div>`).join('')||'No conversations saved yet.';showModal('Conversation history','Saved in the local workspace database',rows);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=async()=>{try{const r=await api(`/api/conversations/${b.dataset.history}`);conversationId=r.conversation.id;conversation.title=r.conversation.title;conversation.messages=r.messages.map(m=>{if(m.role==='assistant'){try{return{role:'assistant',...JSON.parse(m.body),actions:true}}catch{}}return{role:m.role,body:m.body}});$('#modalRoot').innerHTML='';nav('search')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
  function showAbout(){showModal('Singularity','Search ? Context ? Act','This workspace contains synthetic pension, grievance, officer and audit records. External government connections and production sign-in are not configured. Displayed statuses reflect the available records only. No official approval, dispatch, payment or external update is performed.')}
  function applyCaseFilters(){const q=$('#caseFilter').value.toLowerCase(),st=$('#stageFilter').value.toLowerCase().replaceAll(' ','_'),iss=$('#issueFilter').value.toLowerCase().replaceAll(' ','_');const filtered=data.pensions.filter(p=>JSON.stringify(p).toLowerCase().includes(q)&&(!st||p.stage===st)&&(!iss||p.issue===iss));const tbody=$('.data-table tbody');if(tbody)tbody.innerHTML=filtered.slice(0,100).map(p=>`<tr><td><button class="text-link" data-case="${esc(p.id)}">${esc(p.pensioner_name)}</button></td><td>${esc(p.id)}</td><td>${esc(p.district)}</td><td>${esc(p.issue.replaceAll('_',' '))}</td><td>${esc(p.stage.replaceAll('_',' '))}</td><td>${esc(person(p.owner_id)?.name||'—')}</td><td>${p.unresolved?'Unresolved':'Other status'}</td></tr>`).join('');document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>nav('pensions',b.dataset.case))}
  function peopleTab(tabName){document.querySelectorAll('[data-people-tab]').forEach(x=>x.classList.toggle('active',x.dataset.peopleTab===tabName));const root=$('#peopleContent');if(!root)return;if(tabName==='Directory'){root.innerHTML=peopleDirectory();wire();return}if(tabName==='Offices'){root.innerHTML=`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Office</th><th>Location</th><th>Reports to</th><th>Officers listed</th><th>Relationship</th></tr></thead><tbody>${data.offices.map(o=>`<tr><td><b>${esc(o.name)}</b><small>${esc(o.id)}</small></td><td>${esc(o.location)}</td><td>${esc(data.offices.find(x=>x.id===o.parent_id)?.name||'Department')}</td><td>${data.people.filter(p=>p.office_id===o.id).length}</td><td>${['DEE','DOP','AG','TREASURY'].includes(o.id)?'Coordination office':'Department office'}</td></tr>`).join('')}</tbody></table></div>`;return}if(tabName==='Organisation'){root.innerHTML=organisationView();wire();return}if(tabName==='Access'){root.innerHTML=`<div class="panel"><div class="panel-head">Role scopes</div><div class="panel-body"><table class="result-table"><tr><th>Role</th><th>Sample scope</th><th>Approval</th></tr>${[['pension_assistant','Assigned pension records','Propose only'],['grievance_officer','Assigned grievances','Propose only'],['head_of_office','Office scope','Review within configured authority'],['supervisor','Configured department scope','Review within configured authority'],['audit_officer','Authorised audit scope','No case actions'],['system_admin','Metadata only','No content by default']].map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div></div>`;wire();return}if(tabName==='Relationships'){root.innerHTML=`<div class="panel"><div class="panel-head">Case relationships</div><div class="panel-body">${data.pensions.filter(p=>p.id==='PEN-NGN-2026-041'||p.potential_clarification_match).slice(0,10).map(p=>`<div class="mini-row"><div><button class="text-link" data-case="${p.id}"><b>${esc(p.pensioner_name)} · ${esc(p.id)}</b></button><small>Proposal · owner ${esc(person(p.owner_id)?.name||'—')} · related source passages ${data.sources.filter(s=>s.proposal_id===p.id).length}</small></div></div>`).join('')}</div></div>`}else root.innerHTML=`<div class="panel"><div class="panel-head">Officer workload</div><div class="panel-body">${data.people.map(p=>`<div class="mini-row"><div><b>${esc(p.name)}</b><small>${data.pensions.filter(x=>x.owner_id===p.id).length} assigned cases · ${data.tasks.filter(t=>t.assignee_id===p.id).length} tasks · role ${esc(p.role)}</small></div></div>`).join('')}</div></div>`;wire()}
  function personProfile(id){const p=person(id);if(!p)return;const assigned=data.pensions.filter(x=>x.owner_id===id),tasks=data.tasks.filter(x=>x.assignee_id===id);openDrawer(p.name,`${p.designation} &middot; ${p.office_id} &middot; ${p.role}`,`<div class="profile-drawer"><div class="profile-hero"><span class="avatar avatar-lg">${p.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><div><b>${esc(p.name)}</b><small>${esc(p.designation)}</small></div></div><dl class="detail-list"><dt>Office</dt><dd>${esc(data.offices.find(o=>o.id===p.office_id)?.name||p.office_id)}</dd><dt>Reports to</dt><dd>${esc(person(p.manager_id)?.name||'No manager recorded')}</dd><dt>Responsibilities</dt><dd>${esc(responsibility(p.role))}</dd><dt>Assigned cases</dt><dd>${assigned.length} authorised records</dd><dt>Assigned tasks</dt><dd>${tasks.length} authorised tasks</dd><dt>Permissions</dt><dd>${esc(p.role)} ? enforced by workspace API</dd></dl><h3>Assigned work</h3>${assigned.map(c=>`<button class="drawer-row" data-case="${esc(c.id)}"><b>${esc(c.pensioner_name)}</b><small>${esc(c.id)} ? ${esc(c.issue.replaceAll('_',' '))}</small></button>`).join('')||'<p class="quiet">No authorised cases are assigned in the visible records.</p>'}${tasks.map(t=>`<div class="drawer-row"><b>${esc(t.title)}</b><small>${esc(t.status)} ? ${esc(t.case_id||'Workspace task')}</small></div>`).join('')||'<p class="quiet">No tasks are assigned in the visible records.</p>'}<p class="classification">Synthetic officer profile</p></div>`)}
  function init(){parseRoute();api('/api/session').then(async s=>{actor=s.actor;await refresh();render()}).catch(e=>{$('#view').innerHTML=`<div class="page"><h1 class="page-title">Workspace unavailable</h1><p>${esc(e.message)}</p><p>Start the local server with <code>python server.py</code>.</p></div>`})}
  init();
})();
